from ch12_ink import *
R = {}
def row(c, v, verdict, prose): R[(c, v)] = (verdict, prose)

row(12, 1, 'MATERIAL', f'THESE ARE THE STATUTES AND THE JUDGMENTS WHICH YOU SHALL KEEP TO DO IN THE LAND WHICH THE LORD THE GOD OF YOUR FATHERS HAS GIVEN YOU TO POSSESS, ALL THE DAYS THAT YOU LIVE ON THE EARTH. {HP(12, 1, (("אלה", "החקים", "והמשפטים"), "these are the statutes and the judgments — 12:1 and Leviticus 26:46 alone: the header the fold\'s footer"), (("אשר", "תשמרון", "לעשות"), "which you shall keep to do — the paragogic nun, the chapter\'s first of six"), (("כל", "הימים", "אשר", "אתם", "חיים", "על", "האדמה"), "all the days that you live on the earth — 31:13 the one kin"))} {AP(12, 1, (("אלין", "קימיא", "ודיניא"), "these are the statutes and the laws"), (("כל", "יומיא", "די", "אתון", "קימין"), "all the days that you are alive"))} The plural and the singular in one verse (the register); the Sifrei\'s four nouns (59:1-4).')
row(12, 2, 'MATERIAL', f'DESTROY, YOU SHALL DESTROY ALL THE PLACES WHERE THE NATIONS YOU ARE DISPOSSESSING SERVED THEIR GODS, ON THE HIGH MOUNTAINS AND ON THE HILLS AND UNDER EVERY LEAFY TREE. {HP(12, 2, (("אבד", "תאבדון"), "destroy, you shall destroy — the infinitive absolute; the same doubling is \'perish, you shall perish\' at 4:26, 8:19, 30:18"), (("את", "כל", "המקמות"), "all the places — Jeremiah 45:5 the one kin"), (("ותחת", "כל", "עץ", "רענן"), "and under every leafy tree — the Kings\' formula, the Torah\'s one seat"))} {AP(12, 2, (("אבדא", "תאבדון"), "destroy, you shall destroy"), (("ית", "טעותהון"), "their ERRORS — for their gods, the Aramaic\'s word for idols (thirty-two seats in the book)"))} The Sifrei\'s ten times (60:1), the mountains not their gods (60:4).')
row(12, 3, 'MATERIAL', f'AND YOU SHALL TEAR DOWN THEIR ALTARS AND BREAK THEIR PILLARS, AND THEIR ASHERIM YOU SHALL BURN IN FIRE, AND THE IMAGES OF THEIR GODS YOU SHALL CUT DOWN, AND DESTROY THEIR NAME FROM THAT PLACE. {HP(12, 3, (("ונתצתם", "את", "מזבחתם"), "and you shall tear down their altars — the root\'s five Torah seats (7:5, Exodus 34:13 the kin)"), (("ואשריהם", "תשרפון", "באש"), "and their Asherim you shall burn in fire — 7:5\'s burning is the images\', the Asherim there cut down"), (("ואבדתם", "את", "שמם"), "and destroy their name — the fifth verb 7:5 lacks: the renaming (61:7)"), (("מן", "המקום", "ההוא"), "from that place — 17:10 the one kin; the Land the scope (61:6)"))} {AP(12, 3, (("וצלמי", "טעותהון", "תקוצצון"), "and the images of their errors you shall cut down"))} Five verbs where 7:5 had four, two tokens shared in order (computed).')
row(12, 4, 'MATERIAL', f'YOU SHALL NOT DO SO TO THE LORD YOUR GOD. {HP(12, 4, (("לא", "תעשון", "כן", "ליהוה", "אלהיכם"), "you shall not do so to the LORD your God — one seat; 12:31 the singular pair"))} {AP(12, 4, (("לא", "תעבדון", "כן", "קדם", "יי"), "you shall not do so BEFORE the LORD — \'to\' made \'before\', the Aramaic\'s reverence"))} The shortest verse; the Sifrei\'s three readings (61:8).')
row(12, 5, 'MATERIAL', f'BUT TO THE PLACE WHICH THE LORD YOUR GOD WILL CHOOSE FROM ALL YOUR TRIBES TO PUT HIS NAME THERE — HIS DWELLING YOU SHALL SEEK, AND YOU SHALL COME THERE. {HP(12, 5, (("אל", "המקום", "אשר", "יבחר", "יהוה"), "to the place which the LORD will choose — the phrase\'s first seat; \'will choose\' twenty-three in the book, none before"), (("מכל", "שבטיכם"), "from all your tribes — 12:14\'s \'in one of your tribes\' the pair (62:2-3)"), (("לשום", "את", "שמו", "שם"), "to put His name there — Kings quotes it (1 Kings 14:21)"), (("לשכנו", "תדרשו", "ובאת", "שמה"), "His dwelling you shall seek and come there — \'His dwelling\' the Bible\'s one seat"))} {AP(12, 5, (("לאשראה", "שכנתיה", "תמן"), "to make His SHEKHINAH dwell there — the Name made the Presence"), (("לבית", "שכנתיה", "תתבעון"), "the house of His Shekhinah you shall seek — the Aramaic\'s one \'house\' beside 32:40"))} The seeking\'s procedure (62:1), the Name pronounced (62:4).')
row(12, 6, 'MATERIAL', f'AND YOU SHALL BRING THERE YOUR BURNT OFFERINGS AND YOUR SACRIFICES, AND YOUR TITHES AND THE HEAVE OFFERING OF YOUR HAND, AND YOUR VOWS AND YOUR FREEWILL OFFERINGS, AND THE FIRSTLINGS OF YOUR HERD AND YOUR FLOCK. {HP(12, 6, (("עלתיכם", "וזבחיכם"), "your burnt offerings and your sacrifices — the list\'s first seat, defective"), (("ואת", "תרומת", "ידכם"), "and the heave offering of your hand — one seat; the first fruits (63:9)"), (("ובכרת", "בקרכם", "וצאנכם"), "and the firstlings of your herd and flock — the sin and guilt offerings (63:11)"))} {AP(12, 6, (("ונכסת", "קודשיכון"), "and your HOLY sacrifices — the peace offerings named"), (("וית", "אפרשות", "ידכון"), "and the SEPARATION of your hand — the heave offering\'s Aramaic"))} The seven items read as eleven offerings (63:6-11).')
row(12, 7, 'MATERIAL', f'AND YOU SHALL EAT THERE BEFORE THE LORD YOUR GOD AND REJOICE IN ALL THAT YOU PUT YOUR HAND TO, YOU AND YOUR HOUSEHOLDS, WHEREIN THE LORD YOUR GOD HAS BLESSED YOU. {HP(12, 7, (("ואכלתם", "שם", "לפני", "יהוה", "אלהיכם"), "and you shall eat there before the LORD your God — one seat; within the partition (64:1)"), (("ושמחתם", "בכל", "משלח", "ידכם"), "and rejoice in all you put your hand to — the rejoicing peace offerings (64:2)"), (("אתם", "ובתיכם"), "you and your households — his wife (64:4)"))} {AP(12, 7, (("אתון", "ואנש", "בתיכון"), "you and the MEN of your houses — supplied"))} The singular \'has blessed you\' inside the plural (the register).')
row(12, 8, 'MATERIAL', f'YOU SHALL NOT DO AS ALL THAT WE DO HERE TODAY, EVERY MAN WHAT IS RIGHT IN HIS EYES. {HP(12, 8, (("ככל", "אשר", "אנחנו", "עשים", "פה", "היום"), "as all that we do here today — \'we\' the book\'s five; \'here today\' 5:3\'s"), (("איש", "כל", "הישר", "בעיניו"), "every man what is right in his eyes — Judges\' refrain (17:6, 21:25)"))} {AP(12, 8, (("גבר", "כל", "מן", "דכשר", "קדמוהי"), "every man what is FIT before him"))} The high places\' stations (65:1-3), the individual\'s high place (65:4-5).')
row(12, 9, 'MATERIAL', f'FOR YOU HAVE NOT YET COME TO THE REST AND TO THE INHERITANCE WHICH THE LORD YOUR GOD GIVES YOU. {HP(12, 9, (("אל", "המנוחה", "ואל", "הנחלה"), "to the rest and to the inheritance — one seat; the noun\'s three Torah seats (Numbers 10:33 the ark\'s)"), (("עד", "עתה"), "until now — the book\'s one"))} {AP(12, 9, (("לבית", "ניחא", "ולאחסנא"), "to the HOUSE of rest and to the inheritance — the rest made a house"))} Shiloh and Jerusalem disputed (66:2); the Land itself (2:2).')
row(12, 10, 'MATERIAL', f'AND YOU SHALL CROSS THE JORDAN AND DWELL IN THE LAND WHICH THE LORD YOUR GOD GIVES YOU TO INHERIT, AND HE WILL GIVE YOU REST FROM ALL YOUR ENEMIES ROUND ABOUT, AND YOU SHALL DWELL IN SAFETY. {HP(12, 10, (("והניח", "לכם", "מכל", "איביכם", "מסביב"), "and give you rest from all your enemies round about — 25:19\'s and 2 Samuel 7:1\'s clause"), (("וישבתם", "בטח"), "and you shall dwell in safety — Leviticus 25:18-19, 26:5 the kin"))} {AP(12, 10, (("ותיתבון", "לרחצן"), "and you shall dwell securely"))} The three commandments of the entry (67:1), the rest before the house (67:3).')
row(12, 11, 'MATERIAL', f'THEN THE PLACE WHICH THE LORD YOUR GOD WILL CHOOSE TO MAKE HIS NAME DWELL THERE — THERE YOU SHALL BRING ALL THAT I COMMAND YOU: YOUR BURNT OFFERINGS AND YOUR SACRIFICES, YOUR TITHES AND THE HEAVE OFFERING OF YOUR HAND, AND ALL THE CHOICE OF YOUR VOWS WHICH YOU VOW TO THE LORD. {HP(12, 11, (("לשכן", "שמו", "שם"), "to make His name dwell there — the second form (14:23, 16:2, 6, 11; 26:2)"), (("שם", "שמה", "תביאו"), "there — thither you shall bring: the doubled adverb, two partitions (67:4)"), (("וכל", "מבחר", "נדריכם"), "and all the choice of your vows — one seat; from the choicest (68:4)"))} {AP(12, 11, (("די", "תדרון", "קדם", "יי"), "which you vow BEFORE the LORD"))} The longest verse (29 tokens); the second list Jerusalem\'s (68:6).')
row(12, 12, 'MATERIAL', f'AND YOU SHALL REJOICE BEFORE THE LORD YOUR GOD, YOU AND YOUR SONS AND YOUR DAUGHTERS, YOUR MENSERVANTS AND YOUR MAIDSERVANTS, AND THE LEVITE WITHIN YOUR GATES, FOR HE HAS NO PORTION NOR INHERITANCE WITH YOU. {HP(12, 12, (("ובניכם", "ובנתיכם", "ועבדיכם", "ואמהתיכם"), "your sons, daughters, menservants and maidservants — the plural list one seat; the dearer first (69:3)"), (("והלוי", "אשר", "בשעריכם"), "and the Levite within your gates — the plural form one seat"), (("כי", "אין", "לו", "חלק", "ונחלה"), "for he has no portion nor inheritance — 14:27, 29; 10:9 and 18:1 without \'no\'"))} {AP(12, 12, (("ולואה", "די", "בקרויכון"), "and the Levite who is in your cities — \'gates\' made cities"))} The Levite\'s ladder (69:4).')
row(12, 13, 'MATERIAL', f'TAKE HEED TO YOURSELF LEST YOU OFFER YOUR BURNT OFFERINGS IN EVERY PLACE THAT YOU SEE. {HP(12, 13, (("השמר", "לך", "פן"), "take heed to yourself lest — the chapter\'s first of three; a prohibition (70:1)"), (("בכל", "מקום", "אשר", "תראה"), "in every place that you see — one seat; a prophet\'s word the exception (70:3)"))} {AP(12, 13, (("אסתמר", "לך", "דילמא"), "keep yourself lest"))} The singular half begins (the register).')
row(12, 14, 'MATERIAL', f'BUT IN THE PLACE WHICH THE LORD WILL CHOOSE IN ONE OF YOUR TRIBES, THERE YOU SHALL OFFER YOUR BURNT OFFERINGS AND THERE YOU SHALL DO ALL THAT I COMMAND YOU. {HP(12, 14, (("באחד", "שבטיך"), "in one of your tribes — THE CHAPTER\'S ONE NUMBER VERSE [1]; 12:5\'s \'all\' the pair"), (("שם", "תעלה", "עלתיך"), "there you shall offer your burnt offerings — one seat; the rest included (70:5-6)"), (("כל", "אשר", "אנכי", "מצוך"), "all that I command you — the singular form\'s one seat in the book"))} {AP(12, 14, (("בחד", "מן", "שבטיך"), "in one of your tribes"))} The money and the ground (70:4).')
row(12, 15, 'MATERIAL', f'ONLY, WITH ALL THE DESIRE OF YOUR SOUL YOU MAY SLAUGHTER AND EAT FLESH, ACCORDING TO THE BLESSING OF THE LORD YOUR GOD WHICH HE HAS GIVEN YOU, IN ALL YOUR GATES; THE UNCLEAN AND THE CLEAN MAY EAT IT, AS THE GAZELLE AND AS THE HART. {HP(12, 15, (("רק", "בכל", "אות", "נפשך"), "only, with all the desire of your soul — the noun\'s four Torah seats, three in the chapter"), (("תזבח", "ואכלת", "בשר"), "you may slaughter and eat flesh — Leviticus 17:3-5 shares one token in order: the release said in new words"), (("הטמא", "והטהור", "יאכלנו"), "the unclean and the clean may eat it — one dish (71:7)"), (("כצבי", "וכאיל"), "as the gazelle and as the hart — the animal\'s consonants \'the beauty\' elsewhere"))} {AP(12, 15, (("תכוס", "ותיכול", "בשרא"), "you may slaughter and eat flesh — the Aramaic\'s slaughter verb"), (("כבשר", "טביא", "ואילא"), "as the FLESH of the gazelle and the hart — supplied"))} The Sifrei assigns the verse to the redeemed blemished animal (71:1-6).')
row(12, 16, 'MATERIAL', f'ONLY THE BLOOD YOU SHALL NOT EAT; ON THE EARTH YOU SHALL POUR IT LIKE WATER. {HP(12, 16, (("רק", "הדם", "לא", "תאכלו"), "only the blood you (pl.) shall not eat — THE ONE PLURAL VERB IN THE SINGULAR HALF"), (("על", "הארץ", "תשפכנו", "כמים"), "on the earth you shall pour it like water — 12:24, 15:23; Leviticus 17:13\'s dust nowhere"))} {AP(12, 16, (("על", "ארעא", "תשדניה", "כמיא"), "on the earth you shall pour it like water"))} One prohibition, not two (71:13); like water four ways (71:14).')

